use vstd::prelude::*;

verus! {

/// Transpose a non‐empty rectangular matrix of i8's.
/// 
/// # Requirements
/// * `arr.len() >= 1`
/// * all rows of `arr` have the same length
/// 
/// # Ensures
/// * `res.len() == arr[0].len()`
/// * for each `j < res.len()`, `res[j].len() == arr.len()`
/// * for all valid `i,j`, `res[j][i] == arr[i][j]`
fn transpose(arr: Vec<Vec<i8>>) -> (res: Vec<Vec<i8>>)
    requires
        // At least one row
        arr.len() >= 1,
        // Every row has the same number of columns
        forall |i: usize| i < arr.len() ==> arr[i].len() == arr[0].len(),
    ensures
        // The result has as many rows as the input has columns
        res.len() == arr[0].len(),
        // Each row of the result has length equal to the original number of rows
        forall |j: usize| j < res.len() ==> res[j].len() == arr.len(),
        // Element‐wise transposition property
        forall |i: usize, j: usize|
            i < arr.len() && j < arr[0].len() ==>
            res[j][i] == arr[i][j],
{
    let rows = arr.len();
    let cols = arr[0].len();
    // We'll build up `res` one row at a time (one "column" of `arr` at a time).
    let mut res: Vec<Vec<i8>> = Vec::new();
    let mut j: usize = 0;
    while j < cols
        invariant
            // Loop counter is in bounds
            j <= cols,
            // We've built exactly `j` rows so far
            res.len() == j,
            // Each completed row `jj < j` has length = `rows`
            forall |jj: usize| jj < j ==> res[jj].len() == rows,
            // And satisfies the transposition property
            forall |ii: usize, jj: usize|
                jj < j && ii < rows ==>
                res[jj][ii] == arr[ii][jj],
        decreases cols - j,
    {
        // Build the j‐th row of `res` by collecting arr[0][j], arr[1][j], ..., arr[rows-1][j]
        let mut new_row: Vec<i8> = Vec::new();
        let mut i: usize = 0;
        while i < rows
            invariant
                i <= rows,
                new_row.len() == i,
                // new_row[ii] == arr[ii][j] for each ii < i
                forall |ii: usize| ii < i ==> new_row[ii] == arr[ii][j],
            decreases rows - i,
        {
            new_row.push(arr[i][j]);
            i += 1;
        }
        // Append the completed row
        res.push(new_row);
        j += 1;
    }
    res
}

} // end verus!

fn main() {
    // Example usage (outside of Verus verification):
    let m = vec![
        vec![ 1,  2,  3],
        vec![ 4,  5,  6],
        vec![ 7,  8,  9],
    ];
    let t = transpose(m);
    assert_eq!(t, vec![
        vec![1,4,7],
        vec![2,5,8],
        vec![3,6,9],
    ]);
}